"""Move Zeroes — stable partition with a write pointer.

`insert` marks where the next non-zero belongs; everything from `insert` to the
end is zero-filled once the scan is done.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        insert = 0
        for value in nums:
            if value != 0:
                nums[insert] = value
                insert += 1
        for i in range(insert, len(nums)):
            nums[i] = 0
